SQL_DOC.P_SQL:
DECLARE
V_DATE VARCHAR2(8); V_TIME VARCHAR2(8); V_COUNT_CK NUMBER; V_BUYER VARCHAR2(10) := 'KRJINR0004'; V_REVISION VARCHAR2(3) := '00';
V_IF_FLAG VARCHAR2(1) := 'N'; V_ERR_MSG VARCHAR2(300);
BEGIN
IF $LEGACY_END_YN$='Y' THEN
PROC_IF_PROGRESS_IN(V_BUYER,'GR',$LEGACY_GR_NO$,V_REVISION);
ELSE
SELECT COUNT(LEGACY_GR_SEQ), TO_CHAR(SYSDATE,'YYYYMMDD'), TO_CHAR(SYSDATE,'HH24MISS') INTO V_COUNT_CK, V_DATE, V_TIME FROM IF_GRDT WHERE BUYER = NVL(TRIM(V_BUYER) ,' ') AND LEGACY_PO_NO = NVL(TRIM($LEGACY_PO_NO$) ,' ') AND LEGACY_PO_SEQ = NVL(TRIM($LEGACY_PO_SEQ$),' ') AND BUYER_ITEM_NO = NVL(TRIM($BUYER_ITEM_NO$),' ') AND LEGACY_GR_NO = NVL(TRIM($LEGACY_GR_NO$) ,' ') AND REVISION = NVL(TRIM(V_REVISION),' ') ;
IF V_COUNT_CK = 0 THEN
INSERT INTO IF_GRDT( BUYER, STATUS, LEGACY_PO_NO, LEGACY_PO_SEQ, BUYER_ITEM_NO, BUYER_ITEM_NO1, CURRENCY_CODE, UNIT_PRICE, GR_QTY, GR_AMT, GR_DATE, LEGACY_PR_NO, LEGACY_INV_NO, LEGACY_GR_NO, LEGACY_GR_SEQ, REVISION, RO_QTY, RO_AMT, REMARK, ERROR_MSG, REF_IF_NO, REF_IF_NO1, IF_FLAG, BYIT_COMORG_CODE, FILE_NAME, LOAD_DATE, LOAD_TIME ) VALUES ( NVL(TRIM(V_BUYER) ,' '), NVL(TRIM($STATUS$) ,' '), NVL(TRIM($LEGACY_PO_NO$) ,' '), NVL(TRIM($LEGACY_PO_SEQ$) ,' '), NVL(TRIM($BUYER_ITEM_NO$) ,' '), NVL(TRIM($BUYER_ITEM_NO1$),' '), NVL(TRIM($CURRENCY_CODE$) ,' '), NVL($UNIT_PRICE$ , 0), NVL($GR_QTY$ , 0), NVL($GR_AMT$ , 0), NVL(TRIM($GR_DATE$) ,' '), NVL(TRIM($LEGACY_PR_NO$) ,' '), NVL(TRIM($LEGACY_INV_NO$) ,' '), NVL(TRIM($LEGACY_GR_NO$) ,' '), NVL(TRIM($LEGACY_GR_SEQ$) ,' '), NVL(TRIM(V_REVISION) ,' '), NVL($RO_QTY$ , 0), NVL($RO_AMT$ , 0), NVL(TRIM($REMARK$) ,' '), NVL(TRIM(V_ERR_MSG) ,' '), NVL(TRIM($REF_IF_NO$) ,' '), NVL(TRIM($REF_IF_NO1$) ,' '), NVL(TRIM(V_IF_FLAG) ,' '), NVL(TRIM($BYIT_COMORG_CODE$),' '), NVL(TRIM($FILE_NAME$) ,' '), NVL(TRIM(V_DATE) ,' '), NVL(TRIM(V_TIME) ,' ') );
ELSE
UPDATE IF_GRDT SET STATUS = NVL(TRIM($STATUS$) ,' '), BUYER_ITEM_NO1 = NVL(TRIM($BUYER_ITEM_NO1$),' '), CURRENCY_CODE = NVL(TRIM($CURRENCY_CODE$) ,' '), UNIT_PRICE = NVL($UNIT_PRICE$ , 0), GR_QTY = NVL($GR_QTY$ , 0), GR_AMT = NVL($GR_AMT$ , 0), GR_DATE = NVL(TRIM($GR_DATE$) ,' '), LEGACY_PR_NO = NVL(TRIM($LEGACY_PR_NO$) ,' '), LEGACY_INV_NO = NVL(TRIM($LEGACY_INV_NO$) ,' '), LEGACY_GR_NO = NVL(TRIM($LEGACY_GR_NO$) ,' '), LEGACY_GR_SEQ = NVL(TRIM($LEGACY_GR_SEQ$) ,' '), RO_QTY = NVL($RO_QTY$ , 0), RO_AMT = NVL($RO_AMT$ , 0), REMARK = NVL(TRIM($REMARK$) ,' '), ERROR_MSG = NVL(TRIM(V_ERR_MSG) ,' '), REF_IF_NO = NVL(TRIM($REF_IF_NO$) ,' '), REF_IF_NO1 = NVL(TRIM($REF_IF_NO1$) ,' '), IF_FLAG = NVL(TRIM(V_IF_FLAG) ,' '), BYIT_COMORG_CODE = NVL(TRIM($BYIT_COMORG_CODE$),' '), FILE_NAME = NVL(TRIM($FILE_NAME$) ,' '), LOAD_DATE = NVL(TRIM(V_DATE) ,' '), LOAD_TIME = NVL(TRIM(V_TIME) ,' ') WHERE BUYER = NVL(TRIM(V_BUYER) ,' ') AND LEGACY_PO_NO = NVL(TRIM($LEGACY_PO_NO$) ,' ') AND LEGACY_PO_SEQ = NVL(TRIM($LEGACY_PO_SEQ$),' ') AND BUYER_ITEM_NO = NVL(TRIM($BUYER_ITEM_NO$),' ') AND LEGACY_GR_NO = NVL(TRIM($LEGACY_GR_NO$) ,' ') AND REVISION = NVL(TRIM(V_REVISION),' ') ;
END IF;
END IF;
END;
